(function(){var w=document.getElementById("lv-video-reviews");if(!w)return;w.querySelectorAll(".lv-vr-item").forEach(function(it){var v=it.querySelector("video"),b=it.querySelector(".lv-vr-play");function play(){w.querySelectorAll("video").forEach(function(o){if(o!==v){o.pause();var pb=o.parentElement.querySelector(".lv-vr-play");if(pb)pb.style.display="flex"}});if(!v.src){v.src=v.dataset.src}v.muted=false;v.play().catch(function(){v.muted=true;v.play()});b.style.display="none"}b.addEventListener("click",play);v.addEventListener("click",function(){if(v.paused){play()}else{v.pause();b.style.display="flex"}});v.addEventListener("pause",function(){b.style.display="flex"})});})();